func telegramPristineV106(row entity.NamedIdentityProvider) bool {
	zero := strings.Repeat("0", 64)
	return row.ID == "telegram" && row.ProfileID == "telegram.oidc.v1" && row.IdentityIssuer == "https://oauth.telegram.org" && row.ReviewRevision == zero && row.ConfigRevision == zero && row.PolicyRevision == zero && row.SecretGeneration == "0" && row.Name == "" && row.ClientID == "" && row.CallbackURL == "" && row.AuthCiphertext == "" && !row.Enabled && row.VerifiedConfigRevision == "" && row.VerifiedBy == "" && row.VerifiedUserCreatedAt == nil && row.VerifiedBindingID == "" && row.VerifiedBindingCreatedAt == nil
}

func telegramPeelV106(db *gorm.DB, expected []personalKeyBehaviorMigrationEntry) error {
	if len(expected) < 1 || len(expected) > 106 {
		return errors.New("unsupported Telegram fixture boundary")
	}
	for i, row := range expected {
		if row.Version != i+1 || row.AppliedAt == "" {
			return errors.New("invalid Telegram fixture receipts")
		}
	}
	read := func() ([]personalKeyBehaviorMigrationEntry, error) {
		var rows []personalKeyBehaviorMigrationEntry
		err := db.Table("schema_migrations").Order("version").Find(&rows).Error
		return rows, err
	}
	before, err := read()
	if err != nil || !reflect.DeepEqual(before, expected) {
		return errors.New("Telegram fixture receipt mismatch")
	}
	// No new tables are introduced in V106. At older contiguous fixture heads only
	// absent Telegram/v10 authority is accepted; older peels own their exact heads.
	for _, target := range []struct{ table, column string }{{"named_identity_bindings", "provider_id"}, {"named_identity_ceremonies", "provider_id"}, {"sessions", "named_identity_provider_id"}, {"mfa_challenges", "named_identity_provider_id"}} {
		if !db.Migrator().HasTable(target.table) || !db.Migrator().HasColumn(target.table, target.column) {
			continue
		}
		var count int64
		if db.Table(target.table).Where(target.column+" = ?", "telegram").Count(&count).Error != nil || count != 0 {
			return errors.New("retained Telegram authority prevents historical peel")
		}
	}
	for _, table := range []string{"secret_rotation_jobs", "secret_process_verifications"} {
		if db.Migrator().HasTable(table) {
			var count int64
			if db.Table(table).Where("inventory_version >= ?", 10).Count(&count).Error != nil || count != 0 {
				return errors.New("retained v10 inventory prevents historical peel")
			}
		}
	}
	var seed entity.NamedIdentityProvider
	var seedCount int64
	if db.Migrator().HasTable(&entity.NamedIdentityProvider{}) {
		if db.Model(&entity.NamedIdentityProvider{}).Where("id = ?", "telegram").Count(&seedCount).Error != nil {
			return errors.New("Telegram singleton lookup")
		}
	}
	if len(before) <= 105 {
		if seedCount != 0 {
			return errors.New("older fixture retained Telegram singleton")
		}
		return nil
	}
	if seedCount != 1 || db.Session(&gorm.Session{QueryFields: true}).Take(&seed, "id = ?", "telegram").Error != nil || !telegramPristineV106(seed) {
		return errors.New("configured Telegram singleton prevents historical peel")
	}
	checks := []struct {
		model any
		name  string
	}{
		{&discordFixtureProviderV101{}, "ck_namedidentityprovider_profile"},
		{&discordFixtureProviderV101{}, "ck_namedidentityprovider_issuer"},
		{&discordFixtureProviderV101{}, "ck_named_identity_singleton"},
		{&discordFixtureBindingV101{}, "ck_namedidentitybinding_profile"},
		{&discordFixtureBindingV101{}, "ck_namedidentitybinding_issuer"},
		{&discordFixtureBindingV101{}, "ck_named_identity_binding_provider"},
		{&discordFixtureBindingV101{}, "ck_named_identity_binding_kind"},
		{&discordFixtureCeremonyV101{}, "ck_namedidentityceremony_profile"},
		{&discordFixtureCeremonyV101{}, "ck_namedidentityceremony_issuer"},
		{&discordFixtureCeremonyV101{}, "ck_named_identity_ceremony_provider"},
		{&discordFixtureCeremonyV101{}, "ck_named_identity_ceremony_kind"},
		{&discordFixtureCeremonyV101{}, "ck_named_identity_ceremonies_purpose"},
		{&discordFixtureCeremonyV101{}, "ck_named_identity_ceremonies_status"},
		{&telegramHistoricalSessionV105{}, "ck_sessions_oidc_primary"},
		{&telegramHistoricalMFAChallengeV105{}, "ck_mfa_challenges_oidc_primary"},
		{&telegramHistoricalRootJobV105{}, "ck_secret_inventory_version"},
		{&telegramHistoricalRootJobV105{}, "ck_secret_rotation_domain"},
		{&telegramHistoricalRootProcessV105{}, "ck_secret_process_inventory_version"},
	}
	for _, c := range checks {
		st := &gorm.Statement{DB: db}
		if st.Parse(c.model) != nil {
			return errors.New("historical Telegram CHECK parse")
		}
		check, ok := st.Schema.ParseCheckConstraints()[c.name]
		if !ok {
			return errors.New("historical Telegram CHECK absent")
		}
		query := db.Table(st.Schema.Table).Where("NOT (" + check.Constraint + ")")
		if st.Schema.Table == "named_identity_providers" {
			query = query.Where("id <> ?", "telegram")
		}
		var invalid int64
		if query.Count(&invalid).Error != nil || invalid != 0 {
			return errors.New("retained rows exceed V105 fixture authority")
		}
	}
	if database.MigrateThrough(db.Statement.Context, db, 105) == nil {
		return errors.New("V105 admitted V106 fixture")
	}
	checked, err := read()
	if err != nil || !reflect.DeepEqual(before, checked) {
		return errors.New("Telegram fixture changed before DDL")
	}
	var current entity.NamedIdentityProvider
	if db.Session(&gorm.Session{QueryFields: true}).Take(&current, "id = ?", "telegram").Error != nil || !reflect.DeepEqual(seed, current) {
		return errors.New("Telegram singleton changed before DDL")
	}
	removed := db.Where("id = ? AND created_at = ? AND updated_at = ?", "telegram", seed.CreatedAt, seed.UpdatedAt).Delete(&entity.NamedIdentityProvider{})
	if removed.Error != nil || removed.RowsAffected != 1 {
		return errors.New("remove exact pristine Telegram singleton")
	}
	for _, c := range checks {
		if db.Migrator().HasConstraint(c.model, c.name) {
			if db.Migrator().DropConstraint(c.model, c.name) != nil {
				return errors.New("remove Telegram fixture CHECK")
			}
		}
		if db.Migrator().CreateConstraint(c.model, c.name) != nil {
			return errors.New("restore V105 fixture CHECK")
		}
	}
	removed = db.Table("schema_migrations").Where("version = ? AND applied_at = ?", 106, before[105].AppliedAt).Delete(&struct{}{})
	if removed.Error != nil || removed.RowsAffected != 1 {
		return errors.New("remove exact Telegram fixture receipt")
	}
	after, err := read()
	if err != nil || !reflect.DeepEqual(before[:105], after) {
		return errors.New("Telegram peel changed V105 receipt history")
	}
	return nil
}

func legacyTelegramBeforeV106(t *testing.T, db *gorm.DB) {
	t.Helper()
	if err := telegramPeelV106(db, personalKeyBehaviorLedger(t, db)); err != nil {
		t.Fatal(err)
	}
}

// A single registered real-driver scenario: no additional named subtests.
func testTelegramMigration(t *testing.T, db *gorm.DB) {
	ctx, cancel := context.WithTimeout(t.Context(), time.Minute)
	defer cancel()
	original := personalKeyBehaviorLedger(t, db)
	if len(original) != 106 || original[105].Version != 106 {
		t.Fatal("exact V106 startup required")
	}
	var initial entity.NamedIdentityProvider
	if db.Session(&gorm.Session{QueryFields: true}).Take(&initial, "id = ?", "telegram").Error != nil || !telegramPristineV106(initial) {
		t.Fatal("disabled unconfigured Telegram singleton required")
	}
	// Every malformed-ledger refusal is proved before destructive fixture DDL.
	rollback := errors.New("rollback Telegram historical refusal")
	for _, kind := range []string{"changed_receipt", "blank_receipt", "gap", "future", "configured", "retained_binding", "retained_v10"} {
		err := db.Transaction(func(tx *gorm.DB) error {
			var q *gorm.DB
			switch kind {
			case "changed_receipt":
				q = tx.Table("schema_migrations").Where("version = ?", 106).Update("applied_at", "changed-fixture-receipt")
			case "blank_receipt":
				q = tx.Table("schema_migrations").Where("version = ?", 106).Update("applied_at", "")
			case "gap":
				q = tx.Table("schema_migrations").Where("version = ?", 105).Delete(&struct{}{})
			case "future":
				q = tx.Table("schema_migrations").Where("version = ?", 106).Update("version", 107)
			case "configured":
				q = tx.Model(&entity.NamedIdentityProvider{}).Where("id = ?", "telegram").Update("name", "Retained configuration")
			case "retained_binding":
				q = tx.Create(&entity.NamedIdentityBinding{ID: "nib_telegram_peel", ProviderID: "telegram", ProfileID: "telegram.oidc.v1", IdentityIssuer: "https://oauth.telegram.org", UserID: "usr_telegram_peel", UserCreatedAt: initial.CreatedAt, ConfigRevision: strings.Repeat("a", 64), SubjectKind: "string", Subject: "0001", SubjectDigest: strings.Repeat("a", 64), CreatedAt: initial.CreatedAt})
			case "retained_v10":
				q = tx.Create(&entity.SecretRotationJob{ID: "srj_telegram_peel", SourceKeyID: "source", TargetKeyID: "target", CutoverEpoch: 1, ETag: strings.Repeat("a", 64), Status: "migrating", Phase: "migration", InventoryVersion: 10, Domain: 12, ScanGeneration: 1, CountsJSON: "{}"})
			}
			if q == nil || q.Error != nil || q.RowsAffected != 1 {
				return errors.New("construct Telegram historical refusal")
			}
			before := personalKeyBehaviorLedger(t, tx)
			if telegramPeelV106(tx, original) == nil {
				return errors.New("unsafe Telegram historical peel admitted")
			}
			if kind != "changed_receipt" && telegramPeelV106(tx, before) == nil {
				return errors.New("nonpristine Telegram fixture admitted")
			}
			if !reflect.DeepEqual(before, personalKeyBehaviorLedger(t, tx)) {
				return errors.New("refusal changed ledger")
			}
			var saved entity.NamedIdentityProvider
			if tx.Session(&gorm.Session{QueryFields: true}).Take(&saved, "id = ?", "telegram").Error != nil {
				return errors.New("refusal erased singleton")
			}
			return rollback
		})
		if !errors.Is(err, rollback) {
			t.Fatal("Telegram historical refusal", kind, err)
		}
		if !reflect.DeepEqual(original, personalKeyBehaviorLedger(t, db)) {
			t.Fatal("refusal changed original receipt history")
		}
	}
	legacyTelegramBeforeV106(t, db)
	prefix := personalKeyBehaviorLedger(t, db)
	if !reflect.DeepEqual(prefix, original[:105]) {
		t.Fatal("V106 peel changed V105 receipts")
	}
	legacyTelegramBeforeV106(t, db)
	if database.MigrateThrough(ctx, db, 105) != nil || !reflect.DeepEqual(prefix, personalKeyBehaviorLedger(t, db)) {
		t.Fatal("bounded V105 repeat")
	}
	// Retained V9 facts are readable but may not be relabeled as Telegram proof.
	birth := time.Now().UTC().Truncate(time.Microsecond)
	localUser := entity.User{ID: "usr_telegram_upgrade", Email: "telegram-upgrade-local@example.test", Name: "Retained local", PasswordHash: "migration-only", Role: entity.RoleMember, CreatedAt: birth, UpdatedAt: birth}
	emergencyUser := entity.User{ID: "usr_telegram_emergency", Email: "telegram-upgrade-emergency@example.test", Name: "Retained emergency", PasswordHash: "migration-only", Role: entity.RoleAdmin, CreatedAt: birth, UpdatedAt: birth}
	oldJob := entity.SecretRotationJob{ID: "srj_telegram_retained_v9", SourceKeyID: "source", TargetKeyID: "target", CutoverEpoch: 1, ETag: strings.Repeat("a", 64), Status: "migrating", Phase: "migration", InventoryVersion: 9, Domain: 12, ScanGeneration: 1, CountsJSON: "{}"}
	oldProcess := entity.SecretProcessVerification{ProcessID: "spv_telegram_retained_v9", InventoryVersion: 9, PolicyEpoch: 1, KeyManifestDigest: strings.Repeat("b", 64), CryptoVersion: 2, RuntimeSourceDigest: strings.Repeat("c", 64), VerifiedAt: birth}
	local := entity.Session{ID: "ses_telegram_upgrade", UserID: "usr_telegram_upgrade", TokenHash: strings.Repeat("1", 64), CreatedAt: birth, ExpiresAt: birth.Add(time.Hour)}
	emergency := entity.Session{ID: "ses_telegram_emergency", UserID: "usr_telegram_emergency", TokenHash: strings.Repeat("2", 64), PrimaryMethod: "emergency", CreatedAt: birth, ExpiresAt: birth.Add(time.Hour), EmergencyPolicyRevision: strings.Repeat("a", 64), EmergencyUserCreatedAt: &birth, EmergencyMFAGeneration: strings.Repeat("A", 43), EmergencyPasswordDigest: strings.Repeat("c", 64), EmergencyFactorCompletedAt: &birth}
	challenge := entity.MFAChallenge{UserID: local.UserID, Purpose: "login", TokenHash: strings.Repeat("3", 64), PasswordDigest: strings.Repeat("c", 64), Generation: strings.Repeat("A", 43), ExpiresAt: birth.Add(time.Minute)}
	emergencyChallenge := entity.MFAChallenge{UserID: emergency.UserID, Purpose: "emergency", TokenHash: strings.Repeat("4", 64), PasswordDigest: strings.Repeat("c", 64), Generation: strings.Repeat("A", 43), ExpiresAt: birth.Add(time.Minute), PrimaryMethod: "emergency", EmergencyPolicyRevision: strings.Repeat("a", 64), EmergencyUserCreatedAt: &birth, EmergencyMFAGeneration: strings.Repeat("A", 43), EmergencyPasswordDigest: strings.Repeat("c", 64)}
	for _, row := range []any{&localUser, &emergencyUser, &oldJob, &oldProcess, &local, &emergency, &challenge, &emergencyChallenge} {
		if err := db.Create(row).Error; err != nil {
			t.Fatalf("retain V105 authority before Telegram upgrade (%T): %v", row, err)
		}
	}
	capture := func(model any, where string, args ...any) any {
		t.Helper()
		out := reflect.New(reflect.TypeOf(model).Elem()).Interface()
		if db.Session(&gorm.Session{QueryFields: true}).Where(where, args...).Take(out).Error != nil {
			t.Fatal("capture retained Telegram upgrade row")
		}
		return out
	}
	retained := []struct {
		model  any
		where  string
		args   []any
		before any
	}{
		{&localUser, "id = ?", []any{localUser.ID}, nil}, {&emergencyUser, "id = ?", []any{emergencyUser.ID}, nil},
		{&oldJob, "id = ?", []any{oldJob.ID}, nil}, {&oldProcess, "process_id = ?", []any{oldProcess.ProcessID}, nil},
		{&local, "id = ?", []any{local.ID}, nil}, {&emergency, "id = ?", []any{emergency.ID}, nil},
		{&challenge, "user_id = ? AND purpose = ?", []any{challenge.UserID, challenge.Purpose}, nil}, {&emergencyChallenge, "user_id = ? AND purpose = ?", []any{emergencyChallenge.UserID, emergencyChallenge.Purpose}, nil},
	}
	for i := range retained {
		r := &retained[i]
		r.before = capture(r.model, r.where, r.args...)
	}
	var providers []entity.NamedIdentityProvider
	if db.Session(&gorm.Session{QueryFields: true}).Order("id").Find(&providers).Error != nil {
		t.Fatal("capture other named providers")
	}
	assertRetained := func() {
		t.Helper()
		for _, r := range retained {
			if !reflect.DeepEqual(r.before, capture(r.model, r.where, r.args...)) {
				t.Fatal("V106 changed retained authority")
			}
		}
		var after []entity.NamedIdentityProvider
		if db.Session(&gorm.Session{QueryFields: true}).Where("id <> ?", "telegram").Order("id").Find(&after).Error != nil || !reflect.DeepEqual(providers, after) {
			t.Fatal("V106 changed independent named providers")
		}
	}
	migrate := func() {
		t.Helper()
		if err := database.Migrate(ctx, db); err != nil {
			t.Fatal("V106 migration", err)
		}
		rows := personalKeyBehaviorLedger(t, db)
		if len(rows) != 106 || rows[105].Version != 106 || !reflect.DeepEqual(prefix, rows[:105]) {
			t.Fatal("V106 changed released receipt prefix")
		}
		assertRetained()
	}
	var wg sync.WaitGroup
	results := make(chan error, 2)
	for range 2 {
		wg.Go(func() { results <- database.Migrate(ctx, db) })
	}
	wg.Wait()
	close(results)
	for err := range results {
		if err != nil {
			t.Fatal("concurrent V106 startup", err)
		}
	}
	migrate()
	var seeded entity.NamedIdentityProvider
	if db.Session(&gorm.Session{QueryFields: true}).Take(&seeded, "id = ?", "telegram").Error != nil || !telegramPristineV106(seeded) {
		t.Fatal("V106 seed authority")
	}
	repeat := personalKeyBehaviorLedger(t, db)
	migrate()
	if !reflect.DeepEqual(repeat, personalKeyBehaviorLedger(t, db)) {
		t.Fatal("repeat changed migration timestamps")
	}
	// Resume after a fixed CHECK DDL interruption without rewriting any seed/facts.
	if db.Migrator().DropConstraint(&entity.NamedIdentityBinding{}, "ck_namedidentitybinding_profile") != nil {
		t.Fatal("partial V106 CHECK setup")
	}
	q := db.Table("schema_migrations").Where("version = ? AND applied_at = ?", 106, repeat[105].AppliedAt).Delete(&struct{}{})
	if q.Error != nil || q.RowsAffected != 1 {
		t.Fatal("remove exact V106 partial receipt")
	}
	migrate()
	var afterSeed entity.NamedIdentityProvider
	if !db.Migrator().HasConstraint(&entity.NamedIdentityBinding{}, "ck_namedidentitybinding_profile") || db.Session(&gorm.Session{QueryFields: true}).Take(&afterSeed, "id = ?", "telegram").Error != nil || !reflect.DeepEqual(seeded, afterSeed) {
		t.Fatal("partial V106 DDL replay changed singleton")
	}

	removeReceipt := func() {
		t.Helper()
		rows := personalKeyBehaviorLedger(t, db)
		if len(rows) != 106 {
			t.Fatal("exact V106 fault-injection head")
		}
		q := db.Table("schema_migrations").Where("version = ? AND applied_at = ?", 106, rows[105].AppliedAt).Delete(&struct{}{})
		if q.Error != nil || q.RowsAffected != 1 {
			t.Fatal("remove exact V106 metadata-control receipt")
		}
	}
	for _, bad := range []struct {
		model any
		field string
	}{{&githubWrongSubjectWidthV98{}, "Subject"}, {&githubWrongBirthPrecisionV98{}, "UserCreatedAt"}, {&githubWrongOptionalNullV98{}, "VerifiedAt"}} {
		if db.Migrator().AlterColumn(bad.model, bad.field) != nil {
			t.Fatal("construct incompatible V106 column", bad.field)
		}
		removeReceipt()
		if database.Migrate(ctx, db) == nil || !reflect.DeepEqual(prefix, personalKeyBehaviorLedger(t, db)) {
			t.Fatal("V106 admitted incompatible column", bad.field)
		}
		assertRetained()
		var good any = &entity.NamedIdentityBinding{}
		if bad.field == "VerifiedAt" {
			good = &entity.NamedIdentityCeremony{}
		}
		if db.Migrator().AlterColumn(good, bad.field) != nil {
			t.Fatal("restore V106 exact column", bad.field)
		}
		migrate()
	}
	for _, bad := range []any{&githubWrongOwnerIndexV98{}, &githubWrongOwnerOrderV98{}} {
		if database.DropIndex(db, &entity.NamedIdentityBinding{}, "idx_named_identity_member") != nil || db.Migrator().CreateIndex(bad, "idx_named_identity_member") != nil {
			t.Fatal("construct incompatible V106 owner index")
		}
		removeReceipt()
		if database.Migrate(ctx, db) == nil || !reflect.DeepEqual(prefix, personalKeyBehaviorLedger(t, db)) {
			t.Fatal("V106 admitted incompatible owner index")
		}
		assertRetained()
		if database.DropIndex(db, &entity.NamedIdentityBinding{}, "idx_named_identity_member") != nil || db.Migrator().CreateIndex(&entity.NamedIdentityBinding{}, "idx_named_identity_member") != nil {
			t.Fatal("restore V106 owner index")
		}
		migrate()
	}
	telegramConstraintControlsV106(t, db, birth, local, challenge, seeded)
	migrate()
}

func telegramConstraintControlsV106(t *testing.T, db *gorm.DB, birth time.Time, local entity.Session, challenge entity.MFAChallenge, seed entity.NamedIdentityProvider) {
	t.Helper()
	rejected := errors.New("rollback rejected Telegram constraint control")
	admitted := errors.New("rollback unexpectedly admitted Telegram constraint control")
	deny := func(model any, where string, args []any, bad map[string]any) {
		t.Helper()
		err := db.Transaction(func(tx *gorm.DB) error {
			q := tx.Model(model).Where(where, args...).Updates(bad)
			if q.Error == nil {
				return admitted
			}
			return rejected
		})
		if !errors.Is(err, rejected) {
			t.Fatal("Telegram constraint admitted invalid tuple")
		}
	}
	for _, bad := range []map[string]any{{"id": "Telegram"}, {"id": "telegram "}, {"profile_id": "google.oidc.v1"}, {"profile_id": "telegram.oidc.v1 "}, {"identity_issuer": "https://oauth.telegram.org/"}, {"identity_issuer": "https://accounts.google.com"}} {
		deny(&entity.NamedIdentityProvider{}, "id = ?", []any{"telegram"}, bad)
	}
	var afterSeed entity.NamedIdentityProvider
	if db.Session(&gorm.Session{QueryFields: true}).Take(&afterSeed, "id = ?", "telegram").Error != nil || !reflect.DeepEqual(seed, afterSeed) {
		t.Fatal("rejected tuple changed Telegram seed")
	}
	binding := entity.NamedIdentityBinding{ID: "nib_telegram_constraint", ProviderID: "telegram", ProfileID: "telegram.oidc.v1", IdentityIssuer: "https://oauth.telegram.org", UserID: local.UserID, UserCreatedAt: birth, ConfigRevision: strings.Repeat("a", 64), SubjectKind: "string", Subject: "0001", SubjectDigest: strings.Repeat("d", 64), CreatedAt: birth}
	ceremony := entity.NamedIdentityCeremony{ID: "nic_telegram_constraint", ProviderID: "telegram", ProfileID: "telegram.oidc.v1", IdentityIssuer: "https://oauth.telegram.org", ProviderCreatedAt: seed.CreatedAt, StateHash: strings.Repeat("d", 64), CookieHash: strings.Repeat("e", 64), Purpose: "login", Reason: "Schema-only Telegram constraint control", Status: "pending", ConfigRevision: seed.ConfigRevision, PolicyRevision: seed.PolicyRevision, ExpiresAt: birth.Add(time.Minute), CreatedAt: birth}
	if db.Create(&binding).Error != nil || db.Create(&ceremony).Error != nil {
		t.Fatal("positive Telegram typed binding and pending ceremony")
	}
	var storedBinding entity.NamedIdentityBinding
	if db.Session(&gorm.Session{QueryFields: true}).Take(&storedBinding, "id = ?", binding.ID).Error != nil || storedBinding.Subject != "0001" || storedBinding.SubjectKind != "string" {
		t.Fatal("opaque Telegram subject normalized")
	}
	rollback := errors.New("rollback Telegram positive constraint control")
	for _, subject := range []string{"0", "0001", strings.Repeat("~", 255), " leading trailing "} {
		for _, target := range []struct {
			model any
			id    string
		}{{&entity.NamedIdentityBinding{}, binding.ID}, {&entity.NamedIdentityCeremony{}, ceremony.ID}} {
			err := db.Transaction(func(tx *gorm.DB) error {
				want := reflect.New(reflect.TypeOf(target.model).Elem()).Interface()
				if tx.Session(&gorm.Session{QueryFields: true}).Take(want, "id = ?", target.id).Error != nil {
					return errors.New("read exact Telegram subject baseline")
				}
				switch row := want.(type) {
				case *entity.NamedIdentityBinding:
					if row.ID != target.id {
						return errors.New("Telegram binding identity changed")
					}
					row.SubjectKind, row.Subject = "string", subject
				case *entity.NamedIdentityCeremony:
					if row.ID != target.id {
						return errors.New("Telegram ceremony identity changed")
					}
					row.SubjectKind, row.Subject = "string", subject
				default:
					return errors.New("unexpected Telegram subject model")
				}
				q := tx.Model(target.model).Where("id = ?", target.id).Updates(map[string]any{"subject_kind": "string", "subject": subject})
				if q.Error != nil || (q.RowsAffected != 0 && q.RowsAffected != 1) {
					return errors.New("valid opaque Telegram subject rejected")
				}
				got := reflect.New(reflect.TypeOf(target.model).Elem()).Interface()
				if tx.Session(&gorm.Session{QueryFields: true}).Take(got, "id = ?", target.id).Error != nil || !reflect.DeepEqual(want, got) {
					return errors.New("Telegram subject readback changed identity or provenance")
				}
				return rollback
			})
			if !errors.Is(err, rollback) {
				t.Fatal("positive opaque Telegram subject bound")
			}
		}
	}
	for _, bad := range []map[string]any{{"provider_id": "google"}, {"provider_id": "Telegram"}, {"provider_id": "telegram "}, {"profile_id": "google.oidc.v1"}, {"identity_issuer": "https://oauth.telegram.org/"}, {"subject_kind": "integer"}, {"subject_kind": "String"}, {"subject": ""}, {"subject": "line\nfeed"}, {"subject": "tab\tvalue"}, {"subject": "é"}, {"subject": strings.Repeat("x", 256)}} {
		deny(&entity.NamedIdentityBinding{}, "id = ?", []any{binding.ID}, bad)
	}
	for _, bad := range []map[string]any{{"provider_id": "google"}, {"profile_id": "google.oidc.v1"}, {"identity_issuer": "https://oauth.telegram.org/"}, {"subject_kind": "integer"}, {"subject_kind": "string", "subject": ""}, {"subject_kind": "", "subject": "1"}, {"subject_kind": "string", "subject": "line\nfeed"}, {"subject_kind": "string", "subject": "é"}, {"subject_kind": "string", "subject": strings.Repeat("x", 256)}, {"purpose": "LOGIN"}, {"purpose": "unknown"}, {"status": "VERIFIED"}, {"status": "unknown"}} {
		deny(&entity.NamedIdentityCeremony{}, "id = ?", []any{ceremony.ID}, bad)
	}
	sameMember := binding
	sameMember.ID = "nib_telegram_duplicate"
	sameMember.SubjectDigest = strings.Repeat("e", 64)
	if err := db.Transaction(func(tx *gorm.DB) error { return tx.Create(&sameMember).Error }); !errors.Is(err, gorm.ErrDuplicatedKey) {
		t.Fatal("per-provider Telegram member uniqueness")
	}
	sameSubject := binding
	sameSubject.ID = "nib_telegram_same_subject"
	sameSubject.UserID = "usr_telegram_other"
	if err := db.Transaction(func(tx *gorm.DB) error { return tx.Create(&sameSubject).Error }); !errors.Is(err, gorm.ErrDuplicatedKey) {
		t.Fatal("Telegram typed digest uniqueness")
	}
	for _, target := range []struct {
		model        any
		table, where string
		args         []any
	}{{&entity.Session{}, "sessions", "id = ?", []any{local.ID}}, {&entity.MFAChallenge{}, "mfa_challenges", "user_id = ? AND purpose = ?", []any{challenge.UserID, "login"}}} {
		positive := map[string]any{"primary_method": "telegram", "named_identity_provider_id": "telegram", "named_identity_profile_id": "telegram.oidc.v1", "named_identity_binding_id": binding.ID, "named_identity_binding_created_at": birth, "named_identity_config_revision": strings.Repeat("a", 64), "named_identity_policy_revision": strings.Repeat("b", 64), "named_identity_user_created_at": birth}
		q := db.Table(target.table).Where(target.where, target.args...).Updates(positive)
		if q.Error != nil || q.RowsAffected != 1 {
			t.Fatal("complete Telegram primary positive", target.table)
		}
		for _, bad := range []map[string]any{{"primary_method": "google"}, {"primary_method": "Telegram"}, {"primary_method": "telegram "}, {"named_identity_provider_id": "google"}, {"named_identity_profile_id": "google.oidc.v1"}, {"named_identity_binding_id": ""}, {"named_identity_binding_created_at": nil}, {"named_identity_config_revision": "short"}, {"named_identity_policy_revision": "short"}, {"named_identity_user_created_at": nil}, {"oidc_binding_id": "obn_mixed"}, {"oauth_binding_created_at": birth}, {"ldap_config_revision": "mixed"}, {"saml_user_created_at": birth}, {"emergency_policy_revision": strings.Repeat("c", 64)}, {"emergency_user_created_at": birth}, {"emergency_mfa_generation": strings.Repeat("A", 43)}, {"emergency_password_digest": strings.Repeat("c", 64)}, {"emergency_factor_completed_at": birth}} {
			deny(target.model, target.where, target.args, bad)
		}
		if target.table == "mfa_challenges" {
			deny(target.model, target.where, target.args, map[string]any{"purpose": "emergency"})
		}
		reset := map[string]any{"primary_method": "", "named_identity_provider_id": "", "named_identity_profile_id": "", "named_identity_binding_id": "", "named_identity_binding_created_at": nil, "named_identity_config_revision": "", "named_identity_policy_revision": "", "named_identity_user_created_at": nil}
		q = db.Table(target.table).Where(target.where, target.args...).Updates(reset)
		if q.Error != nil || q.RowsAffected != 1 {
			t.Fatal("restore retained local primary")
		}
	}
	if db.Delete(&ceremony).Error != nil || db.Delete(&binding).Error != nil {
		t.Fatal("remove owned Telegram schema controls")
	}
}
